OUT: {  "A": "sq"}

IN: A="x\ny" => {'A': 'x\ny'}
IN: A="x\ty" => {'A': 'xty'}
IN: A="x\ry" => {'A': 'x\ry'}
IN: A="x\\y" => {'A': 'x\\y'}
IN: A="x\"y" => {'A': 'x"y'}
IN: A="x\$y" => {'A': 'x\\'}
IN: A="x\qy" => {'A': 'xqy'}
IN: A="x\ y" => {'A': 'x y'}
IN: A='x\ny' => {'A': 'x\\ny'}
IN: A='x\ty' => {'A': 'x\\ty'}
IN: A=x\ny => {'A': 'x\\ny'}
IN: A = 1 2 => '\x1b[31mdirenv: error invalid line: A = 1 2\x1b[0m\n'
IN: A=1 2 => '\x1b[31mdirenv: error invalid line: A=1 2\x1b[0m\n'
IN: A =  1 => {'A': '1'}
IN: A= 1 => {'A': '1'}

IN: A="$MYVAR" => {'A': 'MV'}
IN: A="\$MYVAR" => {'A': '\\MV'}
IN: A="x\$MYVAR y" => {'A': 'x\\MV y'}
IN: A=${MYVAR} => {'A': 'MV'}
IN: A="\${MYVAR}" => {'A': '\\MV'}
IN: A='$MYVAR' => {'A': '$MYVAR'}
IN: A=\$MYVAR => {'A': '\\MV'}
IN: A="$MYVAR-s" => {'A': 'MV-s'}
IN: A="${MYVAR:-def}" => {'A': 'MV'}
IN: A=$MYVAR$MYVAR => {'A': 'MVMV'}
IN: B="a\nb\nc" => {'B': 'a\nb\nc'}
IN: B="tab\there" => {'B': 'tabthere'}

IN: A=\"\$\{UNSET_VAR:-def\}\" => {'A': 'def'}
IN: A=\"\$\{UNSET_VAR\}\" => {'A': ''}
IN: $'A="multi\nline"' => {'A': 'multi\nline'}
IN: A=\'multi\\nline\' => {'A': 'multi\\nline'}
IN: $'A=1\nA=2' => {'A': '2'}
IN: \#\ only\ a\ comment => {}
IN: '' => {}
IN: A=1 => {'A': '1'}
IN: export\ A => '\x1b[31mdirenv: error invalid line: export A\x1b[0m\n'
IN: A=\"unclosed => '\x1b[31mdirenv: error unclosed quoted value in .env file\x1b[0m\n'
IN: \ \ #indented\ comment => {}
IN: A=\"v\"\ #\ c => {'A': 'v'}
IN: A=\'v\'\ #\ c => {'A': 'v'}
IN: A=v\ #\ c => {'A': 'v'}
IN: A=v#c => {'A': 'v'}
